import numpy as np, itertools, math
S=np.load('skel.npy')
H,W=S.shape
pix=set(map(tuple,np.argwhere(S)))  # (y,x)
def nbrs(p):
    y,x=p
    out=[]
    for dy in(-1,0,1):
        for dx in(-1,0,1):
            if dy==0 and dx==0: continue
            q=(y+dy,x+dx)
            if q in pix: out.append(q)
    return out
deg={p:len(nbrs(p)) for p in pix}
nodes=[p for p in pix if deg[p]!=2]
nodeset=set(nodes)
# cluster nodes
clusters=[]
seen=set()
for p in nodes:
    if p in seen: continue
    comp=[p]; seen.add(p); stack=[p]
    while stack:
        c=stack.pop()
        for q in nodes:
            if q not in seen and abs(q[0]-c[0])<=3 and abs(q[1]-c[1])<=3:
                seen.add(q); stack.append(q); comp.append(q)
    ys=[c[0] for c in comp]; xs=[c[1] for c in comp]
    clusters.append({'pts':set(comp),'c':(sum(xs)/len(xs),sum(ys)/len(ys))})
cid={}
for i,cl in enumerate(clusters):
    for p in cl['pts']: cid[p]=i
# trace edges
edges={}
for i,cl in enumerate(clusters):
    for p in cl['pts']:
        for q in nbrs(p):
            if q in cid and cid[q]==i: continue
            # walk
            path=[p,q]; prev=p; cur=q
            while cur not in cid:
                nx=[r for r in nbrs(cur) if r!=prev]
                nx=[r for r in nx if r not in path[:-1]]
                if not nx: break
                prev,cur=cur,nx[0]
                path.append(cur)
            if cur in cid:
                j=cid[cur]
                if j==i: continue
                key=(min(i,j),max(i,j))
                L=len(path)
                if key not in edges or edges[key]['len']<L:
                    edges[key]={'len':L}
for i,cl in enumerate(clusters):
    print(i,f"({cl['c'][0]:.0f},{cl['c'][1]:.0f})",'npix',len(cl['pts']))
print('EDGES')
for (i,j),v in sorted(edges.items()):
    a=clusters[i]['c']; b=clusters[j]['c']
    d=math.hypot(a[0]-b[0],a[1]-b[1])
    print(f"{i}({a[0]:.0f},{a[1]:.0f}) - {j}({b[0]:.0f},{b[1]:.0f})  len={v['len']} dist={d:.0f}")
